mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    __typename
    ... on PostActionSuccess { post { ...PostFields } }
    ... on MutationError { message }
  }
}

fragment PostFields on Post {
  id
  status
  dueAt
  sentAt
  createdAt
  updatedAt
  channelId
  channelService
  shareMode
  schedulingType
  isCustomScheduled
  externalLink
  via
  text
  error { message supportUrl }
  assets {
    type
    mimeType
    source
    thumbnail
    ... on VideoAsset {
      video { durationMs width height isVideoProcessing isTranscodingRequired thumbnailOffset }
    }
  }
  metadata {
    __typename
    ... on YoutubePostMetadata { title privacy madeForKids isAiGenerated }
    ... on InstagramPostMetadata { type shouldShareToFeed isAiGenerated }
    ... on TiktokPostMetadata { isAiGenerated }
  }
}

